 15→// getOpenCodeDBPath returns the path to OpenCode's SQLite database.
 16→// OpenCode always uses ~/.local/share/opencode/opencode.db (XDG default)
 17→// regardless of platform — it does NOT use ~/Library/Application Support on macOS.
 18→//
 19→// XDG_DATA_HOME overrides the default on all platforms.
 20→func getOpenCodeDBPath() (string, error) {
 21→	dataDir := os.Getenv("XDG_DATA_HOME")
 22→	if dataDir == "" {
 23→		home, err := os.UserHomeDir()
 24→		if err != nil {
 25→			return "", fmt.Errorf("failed to get home directory: %w", err)
 26→		}
 27→		dataDir = filepath.Join(home, ".local", "share")
 28→	}
 29→	return filepath.Join(dataDir, "opencode", "opencode.db"), nil
 30→}
