 32→// runSQLiteQuery executes a SQL query against OpenCode's SQLite database.
 33→// Returns the combined stdout/stderr output.
 34→func runSQLiteQuery(query string, timeout time.Duration) ([]byte, error) {
 35→	dbPath, err := getOpenCodeDBPath()
 36→	if err != nil {
 37→		return nil, fmt.Errorf("failed to get OpenCode DB path: %w", err)
 38→	}
 39→	if _, err := os.Stat(dbPath); os.IsNotExist(err) {
 40→		return nil, fmt.Errorf("OpenCode database not found: %w", err)
 41→	}
 42→
 43→	ctx, cancel := context.WithTimeout(context.Background(), timeout)
 44→	defer cancel()
 45→
 46→	//nolint:gosec // G204: query is constructed from sanitized inputs (escapeSQLiteString)
 47→	cmd := exec.CommandContext(ctx, "sqlite3", dbPath, query)
 48→	output, err := cmd.CombinedOutput()
 49→	if err != nil {
 50→		return output, fmt.Errorf("sqlite3 query failed: %w", err)
 51→	}
 52→	return output, nil
 53→}
