 55→// sessionExistsInSQLite checks whether a session with the given ID exists
 56→// in OpenCode's SQLite database.
 57→func sessionExistsInSQLite(sessionID string) bool {
 58→	query := fmt.Sprintf("SELECT count(*) FROM session WHERE id = '%s';", escapeSQLiteString(sessionID))
 59→	output, err := runSQLiteQuery(query, 5*time.Second)
 60→	if err != nil {
 61→		return false
 62→	}
 63→	return len(output) > 0 && output[0] != '0'
 64→}
