 66→// deleteMessagesFromSQLite removes all messages (and cascading parts) for a session.
 67→// This is used before reimporting a session during rewind so that `opencode import`
 68→// can insert the checkpoint-state messages (import uses ON CONFLICT DO NOTHING).
 69→func deleteMessagesFromSQLite(sessionID string) error {
 70→	// Enable foreign keys so CASCADE deletes work (parts are deleted with messages).
 71→	query := fmt.Sprintf(
 72→		"PRAGMA foreign_keys = ON; DELETE FROM message WHERE session_id = '%s';",
 73→		escapeSQLiteString(sessionID),
 74→	)
 75→	if output, err := runSQLiteQuery(query, 5*time.Second); err != nil {
 76→		return fmt.Errorf("failed to delete messages from OpenCode DB: %w (output: %s)", err, string(output))
 77→	}
 78→	return nil
 79→}
