 81→// runOpenCodeImport runs `opencode import <file>` to import a session into
 82→// OpenCode's SQLite database. The import preserves the original session ID
 83→// from the export file.
 84→func runOpenCodeImport(exportFilePath string) error {
 85→	ctx, cancel := context.WithTimeout(context.Background(), openCodeImportTimeout)
 86→	defer cancel()
 87→
 88→	cmd := exec.CommandContext(ctx, "opencode", "import", exportFilePath)
 89→	if output, err := cmd.CombinedOutput(); err != nil {
 90→		if ctx.Err() == context.DeadlineExceeded {
 91→			return fmt.Errorf("opencode import timed out after %s", openCodeImportTimeout)
 92→		}
 93→		return fmt.Errorf("opencode import failed: %w (output: %s)", err, string(output))
 94→	}
