 99→// escapeSQLiteString escapes single quotes in a string for safe use in SQLite queries.
100→func escapeSQLiteString(s string) string {
101→	result := make([]byte, 0, len(s))
102→	for i := range len(s) {
103→		if s[i] == '\'' {
104→			result = append(result, '\'', '\'')
105→		} else {
106→			result = append(result, s[i])
107→		}
108→	}
109→	return string(result)
